import { createContext, useCallback, useContext, useMemo, useState } from 'react';
import { lloydConstants } from '../Constants';

// Newest wave first, so waves[0] is the default view and waves[1] the wave before it.
const [latestWave, previousWave] = lloydConstants.waves;

export const NO_COMPARISON = 'None';

const defaultValues = {
	selectedYear: latestWave,
	setSelectedYear: () => {},
	comparisonYear: previousWave,
	setComparisonYear: () => {},
	yearlyData: {},
	setYearlyDataForYear: () => {},
	loadedYears: [],
};

const YearContext = createContext(defaultValues);

export const YearProvider = ({ children }) => {
	const [selectedYear, setSelectedYear] = useState(defaultValues.selectedYear);
	const [comparisonYear, setComparisonYear] = useState(defaultValues.comparisonYear);
	const [yearlyData, setYearlyData] = useState({});

	// Stable identity: useData keys its fetch effect on this.
	const setYearlyDataForYear = useCallback((year, rows) => {
		setYearlyData((previous) => ({ ...previous, [year]: rows }));
	}, []);

	const loadedYears = useMemo(() => Object.keys(yearlyData).map(Number), [yearlyData]);

	return (
		<YearContext.Provider
			value={{
				selectedYear,
				setSelectedYear,
				comparisonYear,
				setComparisonYear,
				yearlyData,
				setYearlyDataForYear,
				loadedYears,
			}}
		>
			{children}
		</YearContext.Provider>
	);
};

export const useYearContext = () => useContext(YearContext);
