import { useEffect, useRef, useState } from 'react';
import { asyncBufferFromUrl, parquetReadObjects } from 'hyparquet';
import { compressors } from 'hyparquet-compressors';
import { lloydConstants } from './Constants';
import { useYearContext } from './context/YearContext';

const enrich = (row) => {
	const countryName = lloydConstants.countryCodeToName[row.country_code];
	if (!countryName) return null;

	row.Country = countryName;

	const countryProps = lloydConstants.countriesProps[countryName];
	if (countryProps) {
		row.GlobalRegion = countryProps.region;
		row.CountryIncomeLevel = lloydConstants.reverseIncomeLevels[countryProps.country_income];
	}

	return row;
};

const loadYear = async (year) => {
	const file = await asyncBufferFromUrl({ url: `data/resilience_${year}.parquet` });
	const rows = await parquetReadObjects({ file, compressors });

	// Rows missing a dimension are already dropped at build time, so the only thing
	// left to discard is a country the lookup does not know about.
	return rows.map(enrich).filter((row) => row !== null);
};

export const useData = () => {
	const { selectedYear, comparisonYear, yearlyData, setYearlyDataForYear } = useYearContext();
	const [loading, setLoading] = useState(true);
	const requested = useRef(new Set());

	const hasSelectedYear = Boolean(yearlyData[selectedYear]);

	useEffect(() => {
		// The wave on screen and the one it is compared against are needed now; the rest
		// can arrive while the user reads the chart.
		const urgent = [selectedYear, comparisonYear].filter(
			(year) => typeof year === 'number' && !requested.current.has(year)
		);
		const rest = lloydConstants.waves.filter(
			(year) => !requested.current.has(year) && !urgent.includes(year)
		);

		[...urgent, ...rest].forEach((year) => requested.current.add(year));

		const fetchAll = async () => {
			await Promise.all(
				urgent.map(async (year) => setYearlyDataForYear(year, await loadYear(year)))
			);

			rest.forEach(async (year) => setYearlyDataForYear(year, await loadYear(year)));
		};

		fetchAll();
	}, [selectedYear, comparisonYear, setYearlyDataForYear]);

	useEffect(() => {
		if (hasSelectedYear) setLoading(false);
	}, [hasSelectedYear]);

	return { loading: loading || !hasSelectedYear };
};
